// This file is generated by AI.

// 文件行徽标: git 更改类型 + 诊断数 (ERROR / WARN)。

import { absToRel, STATUS_CLASS } from '../git/util';
import { useAppStore } from '../state/store';

export function FileBadges({ path }: { path: string }) {
  const projectPath = useAppStore((s) => s.projectPath);
  const gitStatus = useAppStore((s) => s.gitStatus);
  const diagnostics = useAppStore((s) => s.diagnostics);

  const rel = projectPath ? absToRel(projectPath, path) : '';
  const staged = gitStatus?.staged ?? [];
  const unstaged = gitStatus?.unstaged ?? [];
  const change = unstaged.find((f) => f.path === rel) ?? staged.find((f) => f.path === rel);

  const diags = diagnostics[path] ?? [];
  const errors = diags.filter((d) => d.severity === 1).length;
  const warns = diags.filter((d) => d.severity === 2).length;

  if (!change && errors === 0 && warns === 0) return null;

  return (
    <span className="file-badges">
      {change ? <span className={`git-file-status ${STATUS_CLASS[change.status] ?? ''}`}>{change.status}</span> : null}
      {errors > 0 ? <span className="diag-badge diag-error">{errors}</span> : null}
      {warns > 0 ? <span className="diag-badge diag-warn">{warns}</span> : null}
    </span>
  );
}
